package edu.campus;
import java.sql.*;
import java.util.*;
public class Db {
 private final String url=Security.config("DB_URL","jdbc:h2:file:./data/placement"),user=Security.config("DB_USER","sa"),password=Security.config("DB_PASSWORD","");
 public Connection connection()throws SQLException{return DriverManager.getConnection(url,user,password);}
 public List<Map<String,Object>> query(String sql,Object...args)throws SQLException{try(Connection c=connection();PreparedStatement p=c.prepareStatement(sql)){bind(p,args);try(ResultSet rs=p.executeQuery()){List<Map<String,Object>> rows=new ArrayList<>();while(rs.next()){Map<String,Object> row=new LinkedHashMap<>();for(int i=1;i<=rs.getMetaData().getColumnCount();i++)row.put(rs.getMetaData().getColumnLabel(i).toLowerCase(Locale.ROOT),rs.getObject(i));rows.add(row);}return rows;}}}
 public Map<String,Object> one(String sql,Object...args)throws SQLException{var rows=query(sql,args);return rows.isEmpty()?null:rows.get(0);}
 public long count(String sql,Object...args)throws SQLException{return ((Number)one(sql,args).values().iterator().next()).longValue();}
 public long update(String sql,Object...args)throws SQLException{try(Connection c=connection();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){bind(p,args);int changed=p.executeUpdate();try(ResultSet rs=p.getGeneratedKeys()){return rs.next()?rs.getLong(1):changed;}}}
 private void bind(PreparedStatement p,Object[] args)throws SQLException{for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);}
 public void init()throws Exception {
  Class.forName("org.h2.Driver");
  for(String sql:List.of(
   "CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password VARCHAR(256) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN ('student','recruiter','admin')),branch VARCHAR(80) DEFAULT '',cgpa DOUBLE PRECISION DEFAULT 0 CHECK(cgpa BETWEEN 0 AND 10),skills VARCHAR(1000) DEFAULT '',resume VARCHAR(80))",
   "CREATE TABLE IF NOT EXISTS jobs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(120) NOT NULL,company VARCHAR(120) NOT NULL,location VARCHAR(120) NOT NULL,kind VARCHAR(20) NOT NULL CHECK(kind IN ('Job','Internship')),description VARCHAR(5000) NOT NULL,min_cgpa DOUBLE PRECISION NOT NULL CHECK(min_cgpa BETWEEN 0 AND 10),branch VARCHAR(80) NOT NULL,stipend VARCHAR(100) NOT NULL,deadline DATE NOT NULL,recruiter_id BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)",
   "CREATE TABLE IF NOT EXISTS applications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,job_id BIGINT NOT NULL REFERENCES jobs(id),student_id BIGINT NOT NULL REFERENCES users(id),status VARCHAR(20) DEFAULT 'Applied' CHECK(status IN ('Applied','Under Review','Shortlisted','Selected','Rejected')),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(job_id,student_id))",
   "CREATE INDEX IF NOT EXISTS idx_jobs_created ON jobs(created_at DESC,id DESC)",
   "CREATE INDEX IF NOT EXISTS idx_jobs_recruiter ON jobs(recruiter_id)",
   "CREATE INDEX IF NOT EXISTS idx_applications_student ON applications(student_id,created_at DESC)",
   "CREATE INDEX IF NOT EXISTS idx_applications_job ON applications(job_id,created_at DESC)"))update(sql);
  String adminEmail=Security.config("ADMIN_EMAIL","").toLowerCase(Locale.ROOT),adminPassword=Security.config("ADMIN_PASSWORD","");
  if(!adminEmail.isBlank()){
   if(!adminEmail.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||adminPassword.length()<12)throw new IllegalArgumentException("ADMIN_EMAIL and ADMIN_PASSWORD (12+ characters) must be configured correctly.");
   account("Placement Officer",adminEmail,"admin",adminPassword);
  }
  String demo=Security.config("DEMO_PASSWORD","");if(!demo.isBlank()){
   if(demo.length()<12||Security.config("APP_ENV","development").equals("production"))throw new IllegalArgumentException("Demo accounts require development mode and a 12+ character DEMO_PASSWORD.");
   long recruiter=account("Meera · Talent Team","recruiter@college.test","recruiter",demo);
   long student=account("Aarav Singh","student@college.test","student",demo);
   update("UPDATE users SET branch='CSE',cgpa=8.4,skills='Java, JavaScript, SQL' WHERE id=? AND branch=''",student);
   if(count("SELECT COUNT(*) FROM jobs")==0){
    String[][] jobs={{"Software Engineer Intern","Northstar Labs","Bengaluru","Internship","Work with our engineering team to build reliable services and thoughtful user experiences. Java and SQL fundamentals are useful.","25000 / month"},{"Graduate Software Engineer","Orbit Technologies","Hyderabad","Job","Join a product team building tools used by thousands of customers. Strong problem solving and web development fundamentals expected.","8–12 LPA"},{"Frontend Developer Intern","Studio Eight","Remote","Internship","Build accessible interfaces with HTML, CSS, Bootstrap and JavaScript. Collaborate closely with design and backend teams.","20000 / month"}};
    for(var j:jobs)update("INSERT INTO jobs(title,company,location,kind,description,min_cgpa,branch,stipend,deadline,recruiter_id) VALUES(?,?,?,?,?,?,?,?,?,?)",j[0],j[1],j[2],j[3],j[4],6.5,"ANY",j[5],java.sql.Date.valueOf(java.time.LocalDate.now().plusDays(30)),recruiter);
   }
  }
 }
 public long account(String name,String email,String role,String raw)throws Exception{var u=one("SELECT id FROM users WHERE email=?",email);return u==null?update("INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)",name,email,Security.hash(raw),role):((Number)u.get("id")).longValue();}
}
